            _ = &analyzer;
            var fetcher = bun.bundle_v2.BundleV2.DependenciesScanner{ .ctx = (&analyzer), .entry_points = cli.positionals[1..], .onFetch = @ptrCast((&Analyzer.onAnalyze)) };
            _ = &fetcher;
